package org.sleepwell.app;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class MotionConfigurationTest {
    @Test public void mediumMatchesExistingSmartWakePolicyExactly(){MotionProfile p=new MotionProfile(1);for(double value:new double[]{0,.08,.119,.12,.3,Double.NaN})for(int samples:new int[]{0,19,20,100})assertEquals(SleepMath.smartWake(900000,1000000,30,value,2,samples),p.smartWake(900000,1000000,30,value,2,samples));}
    @Test public void sensitivityChangesActualWakeEligibilityWithoutChangingRawValue(){double raw=.10;MotionProfile low=new MotionProfile(0),high=new MotionProfile(2);assertEquals(0,low.activeMinutes(raw,1));assertEquals(2,high.activeMinutes(raw,1));assertFalse(low.smartWake(900000,1000000,30,raw,2,30));assertTrue(high.smartWake(900000,1000000,30,raw,2,30));assertEquals(.10,raw,0);assertFalse(high.smartWake(900000,1000000,30,raw,2,19));}
    @Test public void sensitivityAffectsAutomaticStillnessButPreservesRequiredDuration(){AutomaticSleep low=new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0),high=new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0);for(long time=0;time<=AutomaticSleep.QUIET_REQUIRED;time+=200){low.sample(time,new MotionProfile(0).inference(.06),false);high.sample(time,new MotionProfile(2).inference(.06),false);if(time<AutomaticSleep.QUIET_REQUIRED)assertNotEquals(AutomaticSleep.State.START,low.state());}assertEquals(AutomaticSleep.State.START,low.state());assertEquals(AutomaticSleep.State.COLLECTING,high.state());}
    @Test public void invalidValuesCannotBecomeWakeSignals(){MotionProfile high=new MotionProfile(2);for(double raw:new double[]{Double.NaN,Double.POSITIVE_INFINITY,-1}){assertEquals(0,high.activeMinutes(raw,3));assertFalse(high.smartWake(900000,1000000,30,raw,3,30));}try{new MotionProfile(3);fail();}catch(IllegalArgumentException expected){}}
    @Test public void gravityWarmupAndResetDoNotInventMovement(){MotionFilter filter=new MotionFilter();assertNull(filter.sample(0,0,9.81f));assertEquals(0,filter.sample(0,0,9.81f),1e-6);Double motion=filter.sample(1,0,9.81f);assertEquals(.85,motion,.00001);filter.reset();assertNull(filter.sample(1,0,9.81f));}
    @Test public void nonfiniteSensorValuesDoNotPoisonTheFilter(){MotionFilter filter=new MotionFilter();assertNull(filter.sample(Float.NaN,0,0));assertNull(filter.sample(0,0,9.81f));assertNull(filter.sample(0,Float.POSITIVE_INFINITY,0));assertEquals(0,filter.sample(0,0,9.81f),1e-6);}
    @Test public void missingPreviewBinsStayNullAndStaleSamplesExpire(){MotionPreview preview=new MotionPreview();assertEquals(30,preview.bins(0,new MotionProfile(1)).size());assertTrue(preview.bins(0,new MotionProfile(1)).stream().allMatch(Objects::isNull));preview.sample(0,0,0,9.81f);preview.sample(200,1,0,9.81f);assertTrue(preview.recent(200));assertEquals(1,preview.bins(200,new MotionProfile(1)).stream().filter(Objects::nonNull).count());assertFalse(preview.recent(2300));assertTrue(preview.bins(16000,new MotionProfile(1)).stream().allMatch(Objects::isNull));}
    @Test public void previewAndEngineUseIdenticalFilterOnActualSamples(){MotionPreview preview=new MotionPreview();MotionFilter engine=new MotionFilter();preview.sample(0,0,0,9.81f);engine.sample(0,0,9.81f);preview.sample(200,.2f,0,9.81f);double raw=engine.sample(.2f,0,9.81f);List<Double> values=preview.bins(200,new MotionProfile(2));assertEquals(raw*2,values.get(29),1e-8);preview.clear();assertFalse(preview.recent(200));}
}
